<script setup lang="ts">import {ref,computed,onMounted,onUnmounted,watch} from 'vue';import {route} from '../router';import {runs} from '../stores/runs';import {reviews} from '../stores/reviews';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import {fixed} from '../utils/format';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import EmptyState from '../components/common/EmptyState.vue';import StatusPill from '../components/common/StatusPill.vue';import BudgetStrip from '../components/BudgetStrip.vue';import MorrisPlot from '../components/MorrisPlot.vue';import SobolBars from '../components/SobolBars.vue';import FactorTable from '../components/FactorTable.vue';import TrajectoryLedger from '../components/TrajectoryLedger.vue';import CoefficientTable from '../components/CoefficientTable.vue';import WarningNotes from '../components/WarningNotes.vue';const selected=ref(route.value.query.get('run')||'demo-run'),factor=ref(''),action=ref('已核对模型系数、独立均匀物理范围、Morris有符号步长和有限样本指数；仅模拟代理，不当作真实节能收益。'),notice=ref('');const {error,busy,act}=useTask();watch(()=>route.value.query.get('run'),v=>{selected.value=v||'demo-run'});let timer:ReturnType<typeof setInterval>;onMounted(()=>{runs.load();timer=setInterval(runs.load,2000)});onUnmounted(()=>clearInterval(timer));const run=computed(()=>runs.items.value.find(r=>r.id===selected.value)),result=computed(()=>run.value?.result),detail=computed(()=>result.value?.metrics.find((r:any)=>r.factor_id===(factor.value||result.value.metrics[0]?.factor_id)));function submit(){act(async()=>{await reviews.create({run_id:selected.value,action:action.value});notice.value='因子敏感度复核已提交，等待主管批准。'})}</script><template><PageHeading index="04 / 运行底稿" title="基本效应与全局指数，放在同一张记录中。" note="模型、范围、采样参数与响应快照锁定。Morris σ采用样本分母r−1，Sobol VarY采用A/B合并总体方差；保留有限样本负值与大于1估计。"/><div class="run-toolbar"><label>运行记录<select v-model="selected"><option v-for="r in runs.items.value" :key="r.id" :value="r.id">{{r.id==='demo-run'?'XH-C06 基线':r.id.slice(0,8)}} · {{r.status}}</option></select></label><StatusPill v-if="run" :status="run.status"/></div><Notice :message="error||runs.error.value"/><Notice v-if="run?.status==='failed'" :message="run.error"/><EmptyState v-if="run&&['queued','running'].includes(run.status)" text="Redis worker正在生成网格轨迹与Sobol点列，后台结果每两秒刷新。"/><template v-if="run?.status==='completed'&&result"><WarningNotes :rows="result.warnings"/><BudgetStrip :result="result"/><div class="chart-layout"><section><h2>Morris / μ*与σ</h2><MorrisPlot :rows="result.metrics" :selected="detail?.factor_id" @select="factor=$event"/></section><aside class="index-panel"><h2>Sobol / S1与ST</h2><SobolBars :rows="result.metrics"/></aside></div><h2 class="table-heading">因子指数 / 有限样本原值</h2><FactorTable :rows="result.metrics" @select="factor=$event"/><div class="detail-layout"><section><TrajectoryLedger :result="result"/><details class="model-details"><summary>查看本次锁定的系数与交互项</summary><CoefficientTable :model="result.model"/></details></section><aside class="factor-note" v-if="detail"><p class="eyebrow">ELEMENTARY EFFECT RECORD</p><h2>{{detail.factor_id}} · 基本效应明细</h2><p>{{detail.name}} / {{detail.low}}—{{detail.high}} {{detail.unit}}</p><dl><div><dt>μ / μ*</dt><dd>{{fixed(detail.mu,4)}} / {{fixed(detail.mu_star,4)}}</dd></div><div><dt>样本σ / 分母</dt><dd>{{fixed(detail.sigma,4)}} / {{detail.sigma_denominator}}</dd></div></dl><div class="effect-list"><div v-for="(e,i) in detail.effects" :key="i"><span>轨迹{{Number(i)+1}}</span><b>{{fixed(Number(e),5)}}</b></div></div><p>{{result.morris.note}}</p><p>{{result.sobol.note}}</p><p class="hash-note">输入SHA256 {{result.input_sha256}}</p></aside></div><form v-if="canWrite()" class="review-form" @submit.prevent="submit"><label>因子复核说明<textarea v-model="action" rows="4" minlength="8" required></textarea></label><button :disabled="busy">提交因子敏感度复核</button><p v-if="notice" class="success">{{notice}}</p></form></template></template>
